// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(c), amount);
        uint256 contractBefore = address(c).balance;
        uint256 ownerBefore = address(this).balance;
        vm.prank(address(this));
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(ok && address(this).balance == ownerBefore + amount && address(c).balance == contractBefore - amount);
    }
}
